mapper.select:
SELECT dd.*
FROM sys_dict_data dd
WHERE dd.is_deleted = 0
AND dd.tenant_id = #{tenantId}
AND dd.dict_id = #{request.dictId}

    AND (dd.label LIKE CONCAT('%', #{request.keyword}, '%')
         OR dd.value LIKE CONCAT('%', #{request.keyword}, '%'))


    AND dd.status = #{request.status}



        ORDER BY ${request.safeSortField()} ${request.safeSortOrder()}


        ORDER BY dd.sort ASC
